mapper.select:
SELECT 
FROM user_notifications
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{offset}, #{size}

mapper.delete:
DELETE FROM user_notifications
WHERE user_id = #{userId}
  AND rule_id = #{ruleId}
  AND read_at IS NULL

mapper.insert:
INSERT INTO user_notifications (
    id, user_id, rule_id, period_bucket, title, body, link
) VALUES (
    #{id}, #{userId}, #{ruleId}, #{periodBucket}, #{title}, #{body}, #{link}
)

mapper.select:
SELECT 
FROM user_notifications
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit}
